import React, { useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import axios from "axios";


export default function Reports() {

    const localUser = JSON.parse(localStorage.getItem('user'))
    const [user, setUser] = useState([]);

    useEffect(() => {
        const fetchUser = async () => {
            const res = await axios.get('/api/user/' + localUser._id)
            setUser(res.data);

        }
        fetchUser()
}, [localUser._id])
    console.log('log=',user.role_id)
    return (
        <>
                <div className="ReportsButton">
                    {user.role_id!=='1' || user.role_id!=='2' ?<Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>:''}
                    <br/>
                    <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
            </div>
        </>
    )
}
